//! R6a: learn bounded control flow from examples while reusing certified R3.
//! The teacher supplies labels only; executable source is generated by Rust.
use crate::tutor_rust_r2::{self as r2, Expr, Temp};
use crate::tutor_rust_r3 as r3;
use std::error::Error;
use std::fs;
use std::io::{Read, Write};
use std::path::Path;
use std::process::{Command, Stdio};

type Result<T> = std::result::Result<T, Box<dyn Error>>;
type Example = (u8, u8, u8);
const TASKS: usize = 4;
const TRAIN: [(u8, u8); 24] = r3::TRAIN;
const DEV: [(u8, u8); 8] = r3::DEV;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Predicate {
    Less,
    Equal,
    Even,
}

impl Predicate {
    fn eval(self, a: u8, b: u8) -> bool {
        match self {
            Self::Less => a < b,
            Self::Equal => a == b,
            Self::Even => a & 1 == 0,
        }
    }

    fn source(self) -> &'static str {
        match self {
            Self::Less => "a < b",
            Self::Equal => "a == b",
            Self::Even => "a & 1 == 0",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Program {
    Branch(Predicate, usize, usize),
    Repeat(u8, usize),
    Sequence(usize, usize),
}

impl Program {
    fn eval(self, memory: &[Expr], a: u8, b: u8) -> u8 {
        match self {
            Self::Branch(pred, yes, no) => {
                memory[if pred.eval(a, b) { yes } else { no }].eval(a, b)
            }
            Self::Repeat(count, body) => {
                let mut x = a;
                for _ in 0..count {
                    x = memory[body].eval(x, b);
                }
                x
            }
            Self::Sequence(first, second) => {
                let x = memory[first].eval(a, b);
                memory[second].eval(x, b)
            }
        }
    }

    fn source(self) -> String {
        match self {
            Self::Branch(pred, yes, no) => format!(
                "if {} {{ saved_{yes}(a,b) }} else {{ saved_{no}(a,b) }}",
                pred.source()
            ),
            Self::Repeat(count, body) => {
                format!("let mut x=a; for _ in 0..{count} {{ x=saved_{body}(x,b); }} x")
            }
            Self::Sequence(first, second) => {
                format!("let x=saved_{first}(a,b); saved_{second}(x,b)")
            }
        }
    }
}

fn grammar() -> Vec<Program> {
    let mut programs = Vec::new();
    for pred in [Predicate::Less, Predicate::Equal, Predicate::Even] {
        for yes in 0..7 {
            for no in 0..7 {
                if yes != no {
                    programs.push(Program::Branch(pred, yes, no));
                }
            }
        }
    }
    for count in 2..=4 {
        for body in 0..7 {
            programs.push(Program::Repeat(count, body));
        }
    }
    for first in 0..7 {
        for second in 0..7 {
            programs.push(Program::Sequence(first, second));
        }
    }
    programs
}

// Independent wider-integer reference, no calls to the candidate or bank.
// Tasks deliberately have different control-flow and state-update structures.
fn oracle(task: usize, a: u8, b: u8) -> u8 {
    let (a, b) = (u32::from(a), u32::from(b));
    let y = match task {
        0 => {
            if a < b {
                (((a + b) % 256) ^ a) * b
            } else {
                (a & b) * a + b
            }
        }
        1 => {
            if a & 1 == 0 {
                (((a ^ b) + b) % 256) ^ a
            } else {
                (a.min(b) ^ b) + a
            }
        }
        2 => {
            let one = (a * (b + 1) % 256) ^ b;
            let two = (one * (b + 1) % 256) ^ b;
            (two * (b + 1) % 256) ^ b
        }
        3 => {
            let x = (((a + b) % 256) ^ a) * b % 256;
            (x - (x & b)) * b
        }
        _ => unreachable!(),
    };
    (y % 256) as u8
}

pub fn fixture() -> String {
    let mut raw = String::from("SML_TUTOR_R6A_TRAIN_V1\n");
    for task in 0..TASKS {
        for (a, b) in TRAIN {
            raw.push_str(&format!("{task}|{a}|{b}|{}\n", oracle(task, a, b)));
        }
    }
    raw
}

fn admit(raw: &str) -> Result<Vec<Vec<Example>>> {
    if raw.len() > 8192 || !raw.ends_with('\n') {
        return Err("invalid R6a corpus size or termination".into());
    }
    let mut lines = raw.lines();
    if lines.next() != Some("SML_TUTOR_R6A_TRAIN_V1") {
        return Err("invalid R6a corpus marker".into());
    }
    let mut batch = Vec::new();
    for task in 0..TASKS {
        let mut examples = Vec::new();
        for (a, b) in TRAIN {
            let row = lines.next().ok_or("missing R6a TRAIN row")?;
            if row != format!("{task}|{a}|{b}|{}", oracle(task, a, b)) {
                return Err(format!("invalid R6a teacher row task={task}, a={a}, b={b}").into());
            }
            examples.push((
                a,
                b,
                row.rsplit('|').next().ok_or("missing label")?.parse()?,
            ));
        }
        batch.push(examples);
    }
    if lines.next().is_some() {
        return Err("extra R6a TRAIN rows".into());
    }
    Ok(batch)
}

fn memory(parent: &str, child: &str) -> Result<Vec<Expr>> {
    r3::examine(parent, child)?;
    let saved = r3::verified_memory(parent, &r2::grammar())?;
    r3::restore(child, &r3::extend(&saved))
}

fn checkpoint(programs: &[Program]) -> String {
    let mut raw = String::from("SML_TUTOR_R6A_BANK_V1\n");
    for program in programs {
        raw.push_str(&program.source());
        raw.push('\n');
    }
    raw
}

fn restore(raw: &str) -> Result<Vec<Program>> {
    if raw.len() > 8192 || !raw.ends_with('\n') {
        return Err("invalid R6a bank size or termination".into());
    }
    let mut lines = raw.lines();
    if lines.next() != Some("SML_TUTOR_R6A_BANK_V1") {
        return Err("invalid R6a bank marker".into());
    }
    let candidates = grammar();
    let programs: Vec<_> = lines
        .map(|line| {
            candidates
                .iter()
                .find(|p| p.source() == line)
                .copied()
                .ok_or("unknown R6a program")
        })
        .collect::<std::result::Result<_, _>>()?;
    if programs.len() != TASKS || checkpoint(&programs) != raw {
        return Err("invalid R6a bank".into());
    }
    Ok(programs)
}

/// The old memory is an independently examined prerequisite; only admitted
/// TRAIN labels select among the 196 typed programs. Ambiguity fails closed.
pub fn induce(parent: &str, child: &str, raw: &str) -> Result<String> {
    let saved = memory(parent, child)?;
    let candidates = grammar();
    if candidates.len() != 196 || TRAIN.iter().any(|p| DEV.contains(p)) {
        return Err("R6a grammar or split contract".into());
    }
    let mut learned = Vec::new();
    for examples in admit(raw)? {
        if saved
            .iter()
            .any(|expr| examples.iter().all(|&(a, b, y)| expr.eval(a, b) == y))
        {
            return Err("old macro baseline did not abstain".into());
        }
        let mut matching = candidates
            .iter()
            .filter(|p| examples.iter().all(|&(a, b, y)| p.eval(&saved, a, b) == y));
        let chosen = *matching.next().ok_or("R6a synthesis inconsistent")?;
        if matching.next().is_some() {
            return Err("R6a synthesis ambiguous".into());
        }
        learned.push(chosen);
    }
    Ok(checkpoint(&learned))
}

fn compile(saved: &[Expr], programs: &[Program], root: &Path) -> Result<Vec<u8>> {
    let mut source =
        String::from("#![allow(unused_parens,dead_code)]\nuse std::io::{self,Write};\n");
    for (i, expr) in saved.iter().enumerate() {
        source.push_str(&format!(
            "fn saved_{i}(a:u8,b:u8)->u8{{ {} }}\n",
            expr.source()
        ));
    }
    for (i, program) in programs.iter().enumerate() {
        source.push_str(&format!(
            "fn learned_{i}(a:u8,b:u8)->u8{{ {} }}\n",
            program.source()
        ));
    }
    source.push_str("fn main()->io::Result<()> {let mut out=io::BufWriter::new(io::stdout().lock());for a in 0u8..=255{for b in 0u8..=255{out.write_all(&[");
    for i in 0..TASKS {
        source.push_str(&format!("learned_{i}(a,b),"));
    }
    source.push_str("])?;}}out.flush()}\n");
    let file = root.join("r6.rs");
    let binary = root.join("r6");
    fs::write(&file, source)?;
    let compiler = std::env::var_os("RUSTC").unwrap_or_else(|| "rustc".into());
    let result = Command::new(compiler)
        .args([
            "--edition=2021",
            "-Dwarnings",
            "-O",
            "--crate-name",
            "sml_r6a",
        ])
        .arg(&file)
        .arg("-o")
        .arg(&binary)
        .stdin(Stdio::null())
        .output()?;
    if !result.status.success() {
        return Err(String::from_utf8_lossy(&result.stderr).into_owned().into());
    }
    let result = Command::new(&binary)
        .env_clear()
        .current_dir(root)
        .stdin(Stdio::null())
        .output()?;
    if !result.status.success()
        || !result.stderr.is_empty()
        || result.stdout.len() != 65_536 * TASKS
    {
        return Err("R6a compiled execution failed".into());
    }
    Ok(result.stdout)
}

pub fn examine(parent: &str, child: &str, bank: &str) -> Result<[u64; 4]> {
    let saved = memory(parent, child)?;
    let temp = Temp::new()?;
    let path = temp.0.join("r6.bank");
    fs::write(&path, bank)?;
    let programs = restore(&fs::read_to_string(path)?)?;
    let output = compile(&saved, &programs, &temp.0)?;
    let mut totals = [0; 4];
    for a in 0..=255u8 {
        for b in 0..=255u8 {
            let index = usize::from(a) * 256 + usize::from(b);
            let cohort = if TRAIN.contains(&(a, b)) {
                0
            } else if DEV.contains(&(a, b)) {
                1
            } else {
                2 + index % 2
            };
            for (task, program) in programs.iter().enumerate() {
                let expected = oracle(task, a, b);
                if program.eval(&saved, a, b) != expected
                    || output[index * TASKS + task] != expected
                {
                    return Err(format!("R6a exhaustive mismatch task={task}, a={a}, b={b}").into());
                }
                totals[cohort] += 1;
            }
        }
    }
    Ok(totals)
}

fn read(path: &Path) -> Result<String> {
    let mut raw = String::new();
    fs::File::open(path)?.take(8193).read_to_string(&mut raw)?;
    if raw.len() > 8192 {
        return Err("R6a input too large".into());
    }
    Ok(raw)
}

fn qualify(
    parent: &str,
    child: &str,
    train: &str,
    source: &str,
    output: Option<&Path>,
) -> Result<()> {
    let bank = induce(parent, child, train)?;
    let totals = examine(parent, child, &bank)?;
    let retained_r2: u64 = r2::examine(parent)?.iter().sum();
    let retained_r3: u64 = r3::examine(parent, child)?.iter().sum();
    if let Some(path) = output {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)?;
        file.write_all(bank.as_bytes())?;
        file.sync_all()?;
    }
    for (cohort, total) in ["train", "dev", "test", "testtest"].into_iter().zip(totals) {
        println!("SML_TUTOR_R6A_COHORT cohort={cohort} correct={total} total={total}");
    }
    println!("SML_TUTOR_R6A=PASS programs=4 grammar=196 macro_baseline_abstains=4 exact_cases={} retained_r2={retained_r2} retained_r3={retained_r3} source={source}", totals.iter().sum::<u64>());
    Ok(())
}

pub fn run_cli() -> Result<()> {
    let args: Vec<_> = std::env::args_os().skip(1).collect();
    match args.as_slice() {
        [] => {
            let parent = r2::induce(&r2::fixture())?;
            let child = r3::induce(&parent, &r3::fixture())?;
            qualify(&parent, &child, &fixture(), "synthetic_fixture", None)
        }
        [flag, parent, child, train, output] if flag == "--teacher-train" => qualify(
            &read(Path::new(parent))?,
            &read(Path::new(child))?,
            &read(Path::new(train))?,
            "external_inputs",
            Some(Path::new(output)),
        ),
        _ => Err(
            "usage: sml_tutor_rust_r6 [--teacher-train r2.bank r3.bank r6.train r6.bank]".into(),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bounded_control_flow_compiles_and_retains_memory() {
        let parent = r2::induce(&r2::fixture()).unwrap();
        let child = r3::induce(&parent, &r3::fixture()).unwrap();
        let train = fixture();
        let bank = induce(&parent, &child, &train).unwrap();
        assert_eq!(restore(&bank).unwrap().len(), TASKS);
        assert!(bank.contains("if "));
        assert!(bank.contains("for _ in"));
        assert!(bank.contains("let x="));
        assert_eq!(
            examine(&parent, &child, &bank).unwrap().iter().sum::<u64>(),
            262_144
        );
        assert!(admit(&train.replacen("0|0|0|0", "0|0|0|1", 1)).is_err());
        assert!(restore("SML_TUTOR_R6A_BANK_V1\nunsafe{}\n").is_err());
        assert!(induce(&parent, "invalid", &train).is_err());
    }
}
